a.onPostDeserialize:
__ht__function(json, dm, view, datas) {// 扇叶
function animFans() {
	ht.Default.startAnim({
		duration: 5000,
		easing: function (t) { return t  },
		action: function (v, t) {
            var num = 0;
            if(dm.getDataByTag('spfjItem').a('baoJing') && dm.getDataByTag('spfjItem').a('qtkz') === '停止') {
                dm.getDataByTag('fan1').a('rotation', 0 );
            } else{
                dm.getDataByTag('fan1').a('rotation', 0 + (Math.PI * 12 - 0) * v);
            }
		},
		finishFunc: function () {
			animFans();
		}
	});
}
animFans();}
